const $=s=>document.querySelector(s), now=()=>Date.now()+state.offset;
const labels={free:'사용 가능',occupied:'사용 중',away:'이석 중'};
function initial(){return {version:1,density:55,offset:0,mine:null,notes:[],seats:Array.from({length:48},(_,i)=>({id:`${i%8<4?'A':'B'}${String(Math.floor(i/8)*4+i%4+1).padStart(2,'0')}`,status:i%4===0||i%7===0?'free':i%9===0?'away':'occupied',tagged:i%9===0||i%3!==0,power:i%8<2||i%8>5,window:i<8,until:i%9===0&&i%4!==0&&i%7!==0?Date.now()+15*60000:null,reported:false,warning:false}))};}
let state;try{state=JSON.parse(localStorage.getItem('liverary-v1'));if(state?.version!==1||!Array.isArray(state.seats))state=initial();}catch{state=initial();}
let selected=(state.seats.find(s=>s.status==='free')||state.seats[0]).id,filter='all',view='seats',toastTimer;
function save(){try{localStorage.setItem('liverary-v1',JSON.stringify(state));}catch{toast('브라우저 저장을 사용할 수 없어 현재 화면에서만 유지됩니다.');}}
function policy(){return state.density<50?{use:180,grace:20,name:'여유'}:state.density>=80?{use:90,grace:10,name:'혼잡'}:{use:120,grace:15,name:'보통'};}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function note(msg){state.notes.unshift({text:msg,time:now()});state.notes=state.notes.slice(0,30);}
function seat(){return state.seats.find(s=>s.id===selected);}
function remaining(until){const secs=Math.max(0,Math.ceil((until-now())/1000));return `${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;}
function expire(){let changed=false;state.seats.forEach(s=>{if((s.until&&s.until<=now())||(s.sessionUntil&&s.sessionUntil<=now())){s.status='free';s.tagged=false;s.until=null;s.sessionUntil=null;s.reported=false;if(state.mine===s.id)state.mine=null;note(`${s.id} 좌석의 시간이 만료되어 사용 가능한 상태로 전환되었습니다.`);changed=true;}});if(changed){save();render();}else document.querySelectorAll('[data-until]').forEach(el=>el.textContent=remaining(Number(el.dataset.until)));}
function render(){const free=state.seats.filter(s=>s.status==='free').length,p=policy();$('#free-count').textContent=free;$('#occupancy').innerHTML=`${state.density}<small>%</small>`;$('#occupancy-bar').style.width=state.density+'%';$('#crowd-badge').textContent=p.name;$('#crowd-badge').style.color=state.density>=80?'#bb6363':state.density<50?'#428673':'#a77920';$('#density').value=state.density;$('#density-value').textContent=state.density+'%';$('#policy').textContent=`현재 임시 정책: ${p.name} · 기본 이용 ${p.use}분 · 이석/신고 유예 ${p.grace}분 (기본 15분에서 동적 조정)`;$('#notification-count').textContent=state.notes.length;$('#my-dot').textContent=state.mine?'•':'';
$('#seat-grid').innerHTML=state.seats.map(s=>{const dim=filter==='free'?s.status!=='free':filter==='power'?!s.power:filter==='window'?!s.window:false;return `<button class="seat ${s.status} ${s.id===selected?'chosen':''} ${dim?'dim':''}" data-seat="${s.id}" aria-label="${s.id} ${labels[s.status]}${s.power?' 콘센트':''}${s.window?' 창가':''}" aria-pressed="${s.id===selected}">${s.id}${s.power?'<sup>ϟ</sup>':''}</button>`;}).join('');renderDetail();renderMine();}
function renderDetail(){const s=seat(),mine=state.mine===s.id;$('#detail-panel').innerHTML=`<span class="detail-eyebrow">SEAT DETAILS</span><div class="seat-title"><strong>${s.id}</strong><span class="badge">${labels[s.status]}</span></div><span class="seat-sub">${s.id[0]}구역 · ${s.id[0]==='A'?'집중 공간':'오픈 공간'}</span><div class="amenities">${s.power?'<span>ϟ 콘센트</span>':''}${s.window?'<span>▤ 창가</span>':''}<span>♧ 자유석</span></div>${s.status==='free'?`<p>지금 이용할 수 있는 자리예요.<br>착석 후 QR 체크인으로 좌석을 보호하세요.</p>${s.warning?'<p class="warning">방치 물품 수거 경고가 표시된 좌석입니다. 물품이 남아 있다면 직원에게 문의하세요.</p>':''}<button class="button primary" data-action="checkin">이 좌석 체크인</button><button class="text-button" data-action="correct">실제로 사용 중이에요 ↗</button>`:mine?`<p>내가 체크인한 좌석입니다.</p>${s.until?`<div class="timer" data-until="${s.until}">${remaining(s.until)}</div>`:''}${s.reported?'<p class="warning">방치 신고가 접수되었습니다. 자리로 돌아왔다면 복귀를 확인해 주세요.</p>':''}<button class="button primary" data-action="${s.status==='away'?'return':'away'}">${s.status==='away'?'복귀 확인 · 이용 계속':'잠깐 이석'}</button><button class="text-button" data-action="checkout">이용 종료</button>`:`<p>${s.tagged?'QR 체크인으로 보호 중인 좌석입니다.':'QR 체크인하지 않은 좌석입니다.'}</p>${s.until?`<div class="timer" data-until="${s.until}">${remaining(s.until)}</div><p>보호 시간 남음</p>`:''}<button class="button" data-action="report" ${s.reported?'disabled':''}>${s.reported?'신고 접수 · 복귀 확인 대기':'짐만 남아 있어요'}</button>`}<div class="hint">ⓘ &nbsp;자유석은 예약할 수 없어요.<br>도착했을 때 실제 빈자리인지 확인해 주세요.</div>`;}
function renderMine(){const s=state.seats.find(s=>s.id===state.mine);$('#mine-view').innerHTML=`<div class="eyebrow">MY SPACE</div><h1>내 좌석</h1>${s?`<article class="my-card"><span class="badge">${labels[s.status]}</span><h2 style="margin-top:20px">${s.id} <span style="font-size:16px;font-weight:400">중앙도서관 · 2F 자유열람실</span></h2><p>이용 종료까지 <b data-until="${s.sessionUntil}">${remaining(s.sessionUntil)}</b></p>${s.until?`<p>좌석 보호 남은 시간 <b data-until="${s.until}">${remaining(s.until)}</b></p>`:''}${s.reported?'<p class="warning">방치 신고가 접수되었습니다. 자리에 돌아온 뒤 복귀를 확인하세요.</p>':''}<button class="button primary" data-mine="${s.status==='away'?'return':'away'}">${s.status==='away'?'복귀 확인 · 이용 계속':'잠깐 이석'}</button><button class="button" data-mine="checkout">이용 종료</button></article>`:'<article class="my-card"><h2>아직 체크인한 좌석이 없어요</h2><p>빈자리를 찾아 착석한 뒤 QR 체크인을 해 주세요.</p><button class="button primary" data-view="seats">빈자리 찾기</button></article>'}`;}
function navigate(v){view=v;['seats','mine','guide'].forEach(x=>$(`#${x}-view`).hidden=x!==v);document.querySelectorAll('.nav').forEach(el=>el.classList.toggle('active',el.dataset.view===v));}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal').close();}
function confirmAction(title,body,caption,fn){modal(`<div class="modal-icon">◇</div><h2>${title}</h2><p>${body}</p><button class="button primary" id="confirm-action">${caption}</button><button class="button" id="cancel-action">취소</button>`);$('#confirm-action').onclick=()=>{close();fn();};$('#cancel-action').onclick=close;}
function checkin(id){const s=state.seats.find(s=>s.id===id);if(!s){toast('좌석 번호를 확인해 주세요. 예: A01, B04');return false;}if(state.mine){toast(`이미 ${state.mine} 좌석을 이용 중입니다. 먼저 이용을 종료하세요.`);return false;}if(s.status!=='free'){toast('사용 중인 좌석입니다. 빈자리를 선택해 주세요.');return false;}const p=policy();s.status='occupied';s.tagged=true;s.warning=false;s.reported=false;s.until=null;s.sessionUntil=now()+p.use*60000;s.grace=p.grace;state.mine=s.id;selected=s.id;note(`${s.id} 체크인 완료. 이용 ${p.use}분, 이석 보호 ${p.grace}분이 적용됩니다.`);save();render();toast(`${s.id} 체크인 완료! 좌석 보호가 시작됐어요.`);return true;}
function action(type){const s=seat();if(type==='checkin')confirmAction(`${s.id}에 앉아 계신가요?`,'이 데모에서는 좌석 QR 태그를 버튼으로 대신합니다. 실제 착석 후 체크인하는 흐름입니다.','착석 확인 · 체크인',()=>checkin(s.id));
if(type==='correct')confirmAction('실제 사용 중인 자리인가요?',`${s.id}에 사람이 앉아 있다면 사용 중으로 변경합니다. QR 세션은 생성되지 않습니다.`,'사용 중으로 변경',()=>{s.status='occupied';s.tagged=false;s.warning=false;save();render();toast('좌석 상태를 바로잡았어요. 감사합니다!');});
if(type==='report')confirmAction(`${s.id}에 짐만 남아 있나요?`,s.tagged?`태그된 좌석입니다. 이용자에게 데모 알림을 보내고 ${s.grace||policy().grace}분의 유예 시간을 적용합니다. 기존 보호 시간이 있다면 연장하지 않습니다.`:'미태그 좌석입니다. 유예 시간 없이 공석으로 전환하고 방치 물품 수거 경고를 표시합니다. 물품은 직접 옮기지 마세요.','방치 신고 접수',()=>{if(s.reported)return;s.reported=true;if(s.tagged){s.status='away';s.until=s.until||now()+(s.grace||policy().grace)*60000;note(`${s.id} 방치 신고: 이용자에게 복귀·연장 확인 알림을 보냈습니다. (데모)`);toast('신고를 접수하고 이용자 확인을 요청했어요.');}else{s.status='free';s.warning=true;s.until=null;s.sessionUntil=null;note(`${s.id} 미태그 좌석을 공석으로 전환했습니다. 방치 물품 수거 경고가 표시됩니다.`);toast('공석으로 전환했어요. 남은 물품은 직원에게 문의하세요.');}save();render();});
if(type==='away'&&state.mine===s.id){s.status='away';s.until=Math.min(s.sessionUntil,now()+s.grace*60000);save();render();toast(`${s.grace}분 동안 좌석을 보호해요. 시간 내 돌아와 주세요.`);}
if(type==='return'&&state.mine===s.id){s.status='occupied';s.until=null;s.reported=false;save();render();toast('복귀를 확인했어요. 이어서 이용하세요.');}
if(type==='checkout'&&state.mine===s.id)confirmAction('좌석 이용을 마칠까요?','짐을 챙긴 뒤 이용을 종료해 주세요. 다른 이용자에게 빈자리로 표시됩니다.','이용 종료',()=>{s.status='free';s.tagged=false;s.until=null;s.sessionUntil=null;s.reported=false;state.mine=null;save();render();toast('이용을 종료했어요. 다음에 또 만나요!');});}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.seat){selected=b.dataset.seat;render();}if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));render();}if(b.dataset.action)action(b.dataset.action);if(b.dataset.mine){selected=state.mine;action(b.dataset.mine);}});
$('#modal-close').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
let cameraStream=null,scanFrame=0,scanDetector=null,scannerOpen=false;
function stopScanner(){scannerOpen=false;if(scanFrame)cancelAnimationFrame(scanFrame);scanFrame=0;if(cameraStream){cameraStream.getTracks().forEach(track=>track.stop());cameraStream=null;}scanDetector=null;const video=$('#qr-video');if(video)video.srcObject=null;}
function qrSeatId(raw){const value=String(raw||'').trim();if(/^[AB]\d{2}$/i.test(value))return value.toUpperCase();try{const u=new URL(value);const q=u.searchParams.get('seat')||u.searchParams.get('seatId')||u.searchParams.get('seat_id')||u.searchParams.get('id');if(q&&/^[AB]\d{2}$/i.test(q))return q.toUpperCase();const parts=u.pathname.split('/').filter(Boolean),last=parts.at(-1)||'';if(/^[AB]\d{2}$/i.test(last))return last.toUpperCase();}catch{}return null;}
function cameraError(error){stopScanner();const messages={NotAllowedError:'카메라 권한이 허용되지 않았어요. 주소창의 사이트 권한에서 카메라를 허용하거나 좌석 번호를 직접 입력해 주세요.',NotFoundError:'사용할 수 있는 카메라를 찾지 못했어요. 좌석 번호를 직접 입력해 주세요.',NotReadableError:'카메라를 다른 앱에서 사용 중일 수 있어요. 다른 앱을 닫거나 좌석 번호를 직접 입력해 주세요.',OverconstrainedError:'후면 카메라를 사용할 수 없어요. 좌석 번호를 직접 입력해 주세요.'};const el=$('#camera-status');if(el)el.textContent=messages[error?.name]||'카메라를 열지 못했어요. 좌석 번호를 직접 입력해 주세요.';}
async function startScanner(){if(!scannerOpen)return;if(!navigator.mediaDevices?.getUserMedia){cameraError({name:'NotAllowedError'});return;}if(!('BarcodeDetector'in window)){cameraError({name:'NotSupportedError'});return;}try{const supported=await BarcodeDetector.getSupportedFormats();if(!supported.includes('qr_code')){cameraError({name:'NotSupportedError'});return;}scanDetector=new BarcodeDetector({formats:['qr_code']});cameraStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'}}});if(!scannerOpen){cameraStream.getTracks().forEach(track=>track.stop());cameraStream=null;return;}const video=$('#qr-video');video.srcObject=cameraStream;await video.play();$('#camera-status').textContent='좌석 QR을 화면 안에 맞춰 주세요.';const scan=async()=>{if(!scannerOpen||!video.isConnected)return;try{if(video.readyState>=2){const codes=await scanDetector.detect(video);if(codes.length){const id=qrSeatId(codes[0].rawValue);if(!id){$('#camera-status').textContent='좌석 QR 형식을 확인할 수 없어요. 좌석 번호를 직접 입력해 주세요.';}else{stopScanner();close();selected=id;render();if(checkin(id))navigate('mine');else toast(`${id} 좌석 상태를 확인해 주세요.`);return;}}}}catch{}if(scannerOpen)scanFrame=requestAnimationFrame(scan);};scanFrame=requestAnimationFrame(scan);}catch(error){cameraError(error);}}
function openQrScanner(){stopScanner();scannerOpen=true;modal(`<div class="modal-icon">▣</div><h2>좌석 QR 스캔</h2><p>좌석에 붙은 QR을 카메라 화면에 맞춰 주세요. 브라우저에서 카메라 권한을 요청하면 허용해 주세요.</p><div class="camera-wrap"><video id="qr-video" autoplay muted playsinline aria-label="좌석 QR 스캔 카메라"></video><span class="scan-frame" aria-hidden="true"></span></div><p id="camera-status" class="camera-status" role="status">카메라를 준비하고 있어요…</p><div class="manual-scan"><label for="seat-code">카메라를 사용할 수 없나요? 좌석 번호 직접 입력</label><form id="qr-form"><input id="seat-code" placeholder="예: A01" maxlength="3" pattern="[aAbB][0-2][0-9]" required autocomplete="off"><button class="button primary">번호로 체크인</button></form></div>`);$('#qr-form').onsubmit=e=>{e.preventDefault();const id=$('#seat-code').value.trim().toUpperCase();if(checkin(id)){stopScanner();close();navigate('mine');}else if(!state.seats.some(s=>s.id===id))toast('좌석 번호를 확인해 주세요. 예: A01, B04');};startScanner();}
$('#qr-open').onclick=openQrScanner;
$('#modal-close').addEventListener('click',stopScanner);$('#modal').addEventListener('close',stopScanner);$('#modal').addEventListener('cancel',stopScanner);
$('#notifications').onclick=()=>modal(`<div class="modal-icon">♧</div><h2>알림 <span class="badge">데모</span></h2>${state.notes.length?state.notes.map(n=>`<div class="notification-item">${n.text}</div>`).join(''):'<p>아직 알림이 없어요. 체크인과 신고 결과가 여기에 표시됩니다.</p>'}`);
$('#guide-shortcut').onclick=()=>navigate('guide');$('#density').oninput=e=>{state.density=Number(e.target.value);save();render();};$('#advance').onclick=()=>{state.offset+=16*60000;expire();save();render();toast('데모 시간을 16분 진행했어요.');};$('#reset').onclick=()=>confirmAction('데모를 처음 상태로 되돌릴까요?','이 브라우저의 체크인과 신고 기록이 초기화됩니다.','초기화',()=>{state=initial();selected='A01';filter='all';document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter==='all'));save();render();navigate('seats');toast('데모가 초기화됐어요.');});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_library_seats',description:'Read the current simulated library seat states.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({seats:state.seats.map(s=>({id:s.id,status:s.status,power:s.power,window:s.window})),mySeat:state.mine})});document.modelContext.registerTool({name:'select_library_seat',description:'Select a seat to inspect its details without checking in.',inputSchema:{type:'object',properties:{seatId:{type:'string'}},required:['seatId'],additionalProperties:false},execute:input=>{if(!state.seats.some(s=>s.id===input.seatId))throw Error('Invalid seat ID');selected=input.seatId;navigate('seats');render();return {selected};}});}catch{}}
expire();render();setInterval(expire,1000);
